// Score Jobs: code decides the score, not the AI. Same job = same score, every time.
// ===== SETTINGS: change these to tune the agent =====
const CONFIG = {
  minScore: 45,      // daily mode: only jobs at or above this get a draft
  maxDrafts: 5,      // daily mode: at most this many drafts per day
  titleTimes: 2,     // a skill found in the job TITLE counts double
  skills: [          // [label, pattern, points]
    ['n8n', /\bn8n\b/i, 25],
    ['AI automation', /\bai[- ]automation\b|\bai agents?\b|\bagentic\b/i, 15],
    ['automation', /\bautomat(e|ed|ion|ions|ing)\b/i, 10],
    ['RAG', /\brag\b|retrieval[- ]augmented|vector (db|database|store)|\bembeddings?\b/i, 10],
    ['Make/Zapier', /\bmake\.com\b|\bzapier\b|\bintegromat\b/i, 8],
    ['LLMs', /\bllms?\b|\bopenai\b|\bchatgpt\b|\bgpt-?\d|\bclaude\b|\bollama\b|\blangchain\b/i, 8],
    ['chatbots', /\bchat ?bots?\b/i, 8],
    ['Python', /\bpython\b/i, 8],
    ['workflows', /\bworkflows?\b/i, 5],
    ['APIs/webhooks', /\bapis?\b|\bwebhooks?\b/i, 5],
    ['no-code', /\bno[- ]code\b|\blow[- ]code\b/i, 5],
    ['Telegram', /\btelegram\b/i, 4],
    ['Google Sheets', /\bgoogle sheets\b/i, 4],
    ['Docker', /\bdocker\b/i, 4],
    ['virtual assistant', /\bvirtual assistant\b/i, 4],
    ['JavaScript', /\bjavascript\b|\bnode\.?js\b/i, 3],
    ['networking', /\bnetworking\b/i, 3],
  ],
  goodType: /part[- ]?time|contract|freelance|\bgig\b|project[- ]based/i, goodTypePoints: 12,
  philippinesPoints: 8,   // job says Philippines in location or text
  senior: /\b(senior|sr\.?|lead|principal|staff|head|director|vp|manager|architect)\b/i, seniorPoints: -20,
  junior: /\b(junior|jr\.?|entry[- ]level|intern|internship|assistant|trainee)\b/i, juniorPoints: 5,
  redFlags: [
    ['unpaid or commission only', /\bunpaid\b|commission[- ]only|equity[- ]only/i],
    ['asks you to pay a fee', /(registration|training|starter|processing|application) fee|pay (a|the) (fee|deposit)/i],
  ],
  redFlagPoints: -25,
  usOnly: /\b(u\.s\.|us|usa)[- ]based\b|\b(u\.s\.|usa) only\b|must (be|reside|live) in the (u\.s\.|us|usa|united states)/i, usOnlyPoints: -15,
  curve: 60,         // raw points are squeezed into 0-100: 60 raw = 63, 100 raw = 81, 150 raw = 92
};
// ===== END SETTINGS =====

const input = $('Input').first().json;
const mode = input.mode === 'daily' ? 'daily' : 'paste';
let jobs = [];
try { jobs = JSON.parse(input.jobsJson || '[]'); } catch (e) { jobs = []; }

// Jobs we already looked at (one id per line in the seen file)
let seenText = '';
try { seenText = $('Seen Text').first().json.seen || ''; } catch (e) {}
const seen = new Set(seenText.split('\n').map(s => s.trim()).filter(Boolean));

// Can someone in the Philippines apply? Empty or worldwide-ish = yes.
const openToPH = (loc) => {
  const l = String(loc || '').toLowerCase().trim();
  if (!l || l === 'not stated') return true;
  return /worldwide|anywhere|global|asia|apac|philippines|southeast asia|gmt\+8|^remote$/.test(l);
};

const scoreJob = (j) => {
  const title = String(j.title || '');
  const text = [title, j.type, j.location, j.description].join(' \n ');
  let score = 0;
  const matched = [];
  for (const [label, re, pts] of CONFIG.skills) {
    if (re.test(title)) { score += pts * CONFIG.titleTimes; matched.push(label); }
    else if (re.test(text)) { score += pts; matched.push(label); }
  }
  const notes = [];
  if (CONFIG.goodType.test(j.type + ' ' + title)) { score += CONFIG.goodTypePoints; notes.push('part-time/contract'); }
  if (/philippines/i.test(j.location + ' ' + j.description)) { score += CONFIG.philippinesPoints; notes.push('mentions Philippines'); }
  if (CONFIG.senior.test(title)) { score += CONFIG.seniorPoints; notes.push('senior role'); }
  else if (CONFIG.junior.test(title)) { score += CONFIG.juniorPoints; notes.push('junior-friendly'); }
  const flags = [];
  for (const [label, re] of CONFIG.redFlags) if (re.test(text)) { flags.push(label); score += CONFIG.redFlagPoints; }
  if (CONFIG.usOnly.test(text)) { flags.push('may be US-based only'); score += CONFIG.usOnlyPoints; }
  if (!openToPH(j.location)) flags.push('location may not include the Philippines: ' + j.location);
  // Screening instructions hidden in the post, like "start your application with the word BLUE".
  // Many clients reject anyone who misses these, so code finds them and makes sure the draft follows them.
  const desc = String(j.description || '');
  const instructions = desc.split(/(?<=[.!?])\s+|\n+/)
    .filter(s => /(start|begin) (your |the )?(application|message|proposal|reply|cover letter)|subject line|(include|use|write) the (word|phrase|code)|answer (these|the following|this) questions?|so (we|i) know you read/i.test(s))
    .map(s => s.trim()).slice(0, 3);
  const startWord = ((desc.match(/(?:start|begin)\s+(?:your\s+|the\s+)?(?:application|message|proposal|reply|cover letter)\s+with\s+(?:the\s+)?(?:word|phrase|code)?\s*["'“]?([A-Za-z0-9][\w-]*)/i) || [])[1] || '');
  if (instructions.length) notes.push('has application instructions');
  const raw = score;
  score = raw <= 0 ? 0 : Math.round(100 * (1 - Math.exp(-raw / CONFIG.curve)));
  return { ...j, score, raw, matched, notes, flags, instructions, startWord };
};

// Remove duplicates inside this batch (same id, or same title + company)
const unique = [];
const keys = new Set();
for (const j of jobs) {
  const k2 = (String(j.title) + '|' + String(j.company)).toLowerCase();
  if (keys.has(j.id) || keys.has(k2)) continue;
  keys.add(j.id); keys.add(k2);
  unique.push(j);
}

let picked = [];
const stats = { mode, fetched: jobs.length, unique: unique.length, openToPH: 0, isNew: 0, matched: 0, drafted: 0, newIds: [] };

if (mode === 'paste') {
  picked = unique.map(scoreJob);                      // you chose it, so always draft
} else {
  const eligible = unique.filter(j => openToPH(j.location));
  stats.openToPH = eligible.length;
  const fresh = eligible.filter(j => !seen.has(j.id));
  stats.isNew = fresh.length;
  stats.newIds = fresh.map(j => j.id);                // all new ones get marked as seen at the end
  const scored = fresh.map(scoreJob).sort((a, b) => b.score - a.score);
  const good = scored.filter(j => j.score >= CONFIG.minScore);
  stats.matched = good.length;
  stats.topBelow = scored.slice(0, 3).filter(j => j.score < CONFIG.minScore).map(j => `${j.score} ${j.title}`);
  picked = good.slice(0, CONFIG.maxDrafts);
}
stats.drafted = picked.length;

if (picked.length === 0) return [{ json: { empty: true, stats } }];
return picked.map(j => ({ json: { ...j, stats } }));

// Build Note: one Obsidian note + one sheet row per job.
// Ask Qwen ran once per job, in the same order as Score Jobs, so item 0 belongs to job 0.
const jobs = $('Score Jobs').all().map(i => i.json);
const answers = $input.all().map(i => i.json);
const now = DateTime.now().setZone('Asia/Manila');
const today = now.toFormat('yyyy-MM-dd');

// The model should return JSON. Small models sometimes add extra text, so we dig the JSON out.
const readAnswer = (a) => {
  const raw = (a && a.message && a.message.content) || '';
  if (!raw) return { fit: '', gaps: '', proposal: '', problem: 'The local AI did not answer (is Ollama running?).' };
  const tryParse = (t) => { try { return JSON.parse(t); } catch (e) { return null; } };
  const obj = tryParse(raw) || tryParse((raw.match(/\{[\s\S]*\}/) || [''])[0]);
  if (!obj) return { fit: '', gaps: '', proposal: raw.trim(), problem: 'The AI answer was not clean JSON, the raw text is shown as the draft.' };
  return { fit: String(obj.fit || ''), gaps: String(obj.gaps || ''), proposal: String(obj.proposal || ''), problem: '' };
};

// House style: no em dashes (the model forgets sometimes)
const tidy = (t) => String(t || '').replace(/\s*—\s*/g, ', ').replace(/–/g, '-').trim();
const safeName = (t) => String(t || '').replace(/[\\/:*?"<>|#^\[\]]/g, '').replace(/\s+/g, ' ').trim().slice(0, 70);

// Name and portfolio link come from the skills profile
let profile = '';
try { profile = $('Profile Text').first().json.profile || ''; } catch (e) {}
const myName = ((profile.match(/^- Name:\s*(.+)$/m) || [])[1] || '').trim();
const portfolio = ((profile.match(/## Portfolio link\s*\n-\s*(https?:\/\/\S+)/i) || [])[1] || '[portfolio link]');
const escRe = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Safety nets: code makes sure these are right, even if the small model forgets
const finish = (draft, j) => {
  let d = draft;
  if (j.startWord && !d.toLowerCase().startsWith(j.startWord.toLowerCase())) d = j.startWord + '\n\n' + d;   // screening word first
  const nameAtEnd = myName ? new RegExp('\\s*' + escRe(myName) + '\\s*$', 'i') : null;
  if (!/https?:\/\/|\[portfolio link\]/i.test(d)) {                                                      // portfolio line before the name
    d = nameAtEnd && nameAtEnd.test(d) ? d.replace(nameAtEnd, '\n\n' + portfolio + '\n' + myName) : d + '\n\n' + portfolio;
  }
  if (nameAtEnd && !nameAtEnd.test(d)) d += '\n' + myName;                                                // sign with my name
  return d;
};

return jobs.map((j, i) => {
  const a = readAnswer(answers[i]);
  const fit = tidy(a.fit), gaps = tidy(a.gaps);
  const proposal = a.proposal ? finish(tidy(a.proposal), j) : '';
  const fileName = `${today} ${j.score} ${safeName(j.title)} - ${safeName(j.company || j.source)}`;
  const yaml = (v) => JSON.stringify(String(v || ''));
  const content = [
    '---',
    'type: job-lead',
    'status: new',
    `score: ${j.score}`,
    `source: ${yaml(j.source)}`,
    `company: ${yaml(j.company)}`,
    `job_type: ${yaml(j.type)}`,
    `location: ${yaml(j.location)}`,
    `pay: ${yaml(j.pay)}`,
    `link: ${yaml(j.url)}`,
    `found: ${today}`,
    '---',
    `# ${j.title}${j.company ? ' (' + j.company + ')' : ''}`,
    '',
    `**Score:** ${j.score}/100`,
    `**Matched skills:** ${j.matched.join(', ') || 'none'}`,
    j.notes.length ? `**Notes:** ${j.notes.join(', ')}` : null,
    j.flags.length ? `**Check first:** ${j.flags.join('; ')}` : null,
    `**Why it fits:** ${fit || '-'}`,
    `**Gaps:** ${gaps || '-'}`,
    a.problem ? `\n> [!warning] ${a.problem}` : null,
    '',
    '## Draft proposal (review and edit before sending)',
    '',
    proposal || '(no draft)',
    '',
    '## Job post',
    '',
    `Type: ${j.type || '-'} | Location: ${j.location || '-'} | Pay: ${j.pay || '-'}`,
    '',
    String(j.description || '').slice(0, 2500),
    '',
    `Source: ${/^https?:/.test(j.url) ? `[${j.source}](${j.url})` : j.source + ' (pasted by hand)'}. Found by Job Hunter Agent, drafted by qwen3:8b on ${now.toFormat('yyyy-MM-dd HH:mm')}. Nothing was sent.`,
    '',
    '#job-lead',
    '',
  ].filter(line => line !== null).join('\n');

  const row = {
    Date: today, Score: j.score, Title: j.title, Company: j.company, Source: j.source,
    Type: j.type, Location: j.location, Pay: j.pay, Link: j.url,
    Matched: j.matched.join(', '), Flags: j.flags.join('; '), Fit: fit, Gaps: gaps,
    Draft: proposal, Status: 'new', Note: fileName,
  };
  return { json: { id: j.id, fileName, content, row, score: j.score, title: j.title, company: j.company, source: j.source, url: j.url, fit, gaps, proposal, matched: j.matched, flags: j.flags } };
});

// Digest: the Telegram message, the "seen" list and the log line.
const stats = $('Score Jobs').first().json.stats;
let notes = [];
try { notes = $('Build Note').all().map(i => i.json); } catch (e) { notes = []; }   // no jobs today = Build Note never ran

const esc = (t) => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const now = DateTime.now().setZone('Asia/Manila');
let text = '';

if (stats.mode === 'paste') {
  const n = notes[0];
  if (!n) {
    text = '📋 Job Hunter: the pasted job was empty, nothing to score.';
  } else {
    text = `📋 <b>Pasted job scored ${n.score}/100</b>\n<b>${esc(n.title)}</b>${n.company ? ' · ' + esc(n.company) : ''} (${esc(n.source)})\n`
      + `Matched: ${esc(n.matched.join(', ') || 'none')}\n`
      + (n.flags.length ? `⚠️ ${esc(n.flags.join('; '))}\n` : '')
      + `Why: ${esc(n.fit || '-')}\nGaps: ${esc(n.gaps || '-')}\n\n`
      + `<b>Draft (review before sending):</b>\n${esc(n.proposal).slice(0, 2800)}\n\n`
      + `Saved to output/job-leads. Nothing was sent.`;
  }
} else if (notes.length === 0) {
  text = `🎯 Job Hunter: no new matches today.\nChecked ${stats.fetched} jobs, ${stats.openToPH} open to PH, ${stats.isNew} new.`
    + (stats.topBelow && stats.topBelow.length ? `\nClosest: ${esc(stats.topBelow.join(' | '))}` : '');
} else {
  const lines = notes.map((n, i) =>
    `${i + 1}. <b>${n.score}</b> · <a href="${esc(n.url)}">${esc(n.title)}</a>${n.company ? ' · ' + esc(n.company) : ''} (${esc(n.source)})`
    + (n.flags.length ? `\n   ⚠️ ${esc(n.flags.join('; '))}` : '')
    + (n.fit ? `\n   ${esc(n.fit).slice(0, 220)}` : ''));
  text = `🎯 <b>Job Hunter: ${notes.length} new match${notes.length > 1 ? 'es' : ''}</b>\n`
    + `Checked ${stats.fetched} jobs, ${stats.openToPH} open to PH, ${stats.isNew} new.\n\n`
    + lines.join('\n\n')
    + `\n\nDrafts are in the Job Hunter sheet and output/job-leads. Review, edit, then apply yourself.`;
}

// Mark jobs as seen so tomorrow only brings new ones. Pasted jobs are not added.
const seenLines = (stats.newIds || []).map(id => id + '\n').join('');
const logLine = `- ${now.toFormat('yyyy-MM-dd HH:mm')} | ${stats.mode} | fetched ${stats.fetched} | open to PH ${stats.openToPH} | new ${stats.isNew} | drafted ${notes.length}`
  + (notes.length ? ' | ' + notes.map(n => `[[${n.fileName}]]`).join(', ') : '') + '\n';

return [{ json: { text: text.slice(0, 4000), seenLines: seenLines || '', hasSeen: seenLines.length > 0, logLine } }];
